  ((select id from trips limit 1), NULL, 0, 'Surabaya', 'Indonésie', 1, -7.2462836, 112.7377674, 'Départ Lille → Paris en train (74 €, le 07/10). Vol international Paris → Kuala Lumpur via Etihad, départ 21h25 (602 €). Arrivée à Kuala Lumpur à 19h45 (08/10), puis vol Kuala Lumpur → Surabaya via AirAsia, départ 21h55 arrivée 23h30 (184,75 €, réservé).', 'Hôtel proche de la gare de Surabaya Gubeng, 25 €/nuit. https://www.booking.com/hotel/id/delapandelapan-embong-kenongo.fr.html', 885.75, 0, '[]'::jsonb, '[]'::jsonb),
  ((select id from trips limit 1), NULL, 1, 'Cemoro Lawang', 'Indonésie', 1, -7.9420691, 112.9529769, 'Surabaya → Cascade de Madakaripura → Cemoro Lawang en voiture avec chauffeur, arrêt à la cascade sur le trajet (≈65 €, entre 45 et 65 €).', 'Plusieurs options notées dans le fichier source, à confirmer : Homestay Lereng Bromo (https://www.booking.com/hotel/id/homestay-lereng-bromo.fr.html) / Cellino Homestay (https://www.booking.com/hotel/id/cellino-homestay.fr.html) / Hotel Pesona Bromo Homestay, 34 € (prélevé le 06/10).', 99, 0, '[{"id": "madakaripura", "title": "Cascade Madakaripura", "place": "Madakaripura, Java", "notes": "Guide local obligatoire, 1h30 à 2h sur place, escale sur le trajet vers Cemoro Lawang.", "estimatedPrice": 0, "price": 0, "lat": null, "lng": null}, {"id": "bukit-mentigen", "title": "Coucher de soleil - Bukit Mentigen", "place": "Bukit Mentigen, Cemoro Lawang", "notes": "Point de vue à 20 min à pied du village, vers 16h30.", "estimatedPrice": 0, "price": 0, "lat": null, "lng": null}]'::jsonb, '[]'::jsonb),
  ((select id from trips limit 1), NULL, 2, 'Tumpak Sewu (Pronojiwo)', 'Indonésie', 2, -8.2116602, 112.9420495, 'Lever à 3h, ascension à pied depuis Cemoro Lawang vers King Kong Hill / Seruni Point pour le lever de soleil sur le Bromo, puis Jeep 4x4 privé via la Mer de Sable et la Savane de Jemplang jusqu''à Pronojiwo (≈85 €, entre 70 et 85 €).', 'Sambas Cottages, 2 nuits, 37 €/nuit (prélevé le 08/10). https://www.booking.com/hotel/id/sambas-cottages.fr.html — Alternative notée : Indah Damai Cottages, 49-58 €. https://www.booking.com/hotel/id/indah-damai-cottages.fr.html', 189, 0, '[{"id": "tumpak-sewu", "title": "Descente Tumpak Sewu + Goa Tetes", "place": "Tumpak Sewu, Pronojiwo", "notes": "Descente en échelles de bambou et ponts de corde jusqu''au fond du canyon, puis grotte et cascades de Goa Tetes.", "estimatedPrice": 0, "price": 0, "lat": null, "lng": null}, {"id": "kapas-biru", "title": "Cascade Kapas Biru (scooter)", "place": "Kapas Biru, Pronojiwo", "notes": "Location scooter à l''homestay (~50 000 IDR / ~3 €), descente 30 min au milieu des rizières. Alternative : cascade Coban Sriti.", "estimatedPrice": 30, "price": 30, "lat": null, "lng": null}]'::jsonb, '[]'::jsonb),
  ((select id from trips limit 1), NULL, 3, 'Surabaya', 'Indonésie', 1, -7.2462836, 112.7377674, 'Transfert Pronojiwo → Gare de Klakah (Lumajang) en voiture, ≈1h15 (≈20 €, entre 15 et 20 €), puis train Klakah (KK) → Surabaya Gubeng (SGU), 2h30 (≈10 €).', 'Hôtel à confirmer avant le vol matinal du lendemain.', 30, 0, '[]'::jsonb, '[]'::jsonb),
  ((select id from trips limit 1), NULL, 4, 'Labuan Bajo', 'Indonésie', 1, -8.4944201, 119.8855688, 'Vol Citilink Surabaya → Labuan Bajo, départ 05h30 arrivée 07h35 (99,68 €, réservé via Traveloka). Vol complémentaire Air Asia, départ 09h00 arrivée 10h10 (146,47 €, réservé).', 'Plusieurs options notées, à confirmer : Komodo Lodge, 35 € + 33 €/nuit (https://www.booking.com/hotel/id/komodo-lodge.fr.html) / World BnB, 33 €/nuit (https://www.booking.com/hotel/id/world-bnb.fr.html) / Pavilla Labuan Bajo, 36 €/nuit (https://www.booking.com/hotel/id/pavilla-labuan-bajo.fr.html).', 281.15, 0, '[]'::jsonb, '[]'::jsonb),
