-- Import de l'itinéraire réel depuis "Voyage indonesie.xlsx"
-- Remplace les 5 étapes de test par les 11 vraies étapes du voyage (8-29 oct. 2026).
-- À exécuter dans Supabase > SQL Editor. Vérifie le résultat avant de fermer l'éditeur.

begin;

-- 1) Nettoyage des 5 étapes de test actuelles (et de leurs notes/documents liés)
delete from step_notes where step_id in (select id from steps where trip_id = (select id from trips limit 1));
delete from step_documents where step_id in (select id from steps where trip_id = (select id from trips limit 1));
delete from steps where trip_id = (select id from trips limit 1);

-- 2) La date de début du voyage correspond à l'arrivée à Surabaya
update trips set start_date = '2026-10-08' where id = (select id from trips limit 1);

-- 3) Les 11 étapes du voyage

commit;
